-- Accounts, security and the audit trail.
-- Portable SQL: text ids generated by the application, timestamps passed in by the application.

CREATE TABLE settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
);

CREATE TABLE users (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL UNIQUE,                       -- always stored lower-case
  name TEXT,
  role TEXT NOT NULL CHECK (role IN ('admin','manager','viewer','user')),
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','disabled')),
  password_hash TEXT NOT NULL,
  token_version INTEGER NOT NULL DEFAULT 0,         -- bumped on password change: signs the user out everywhere
  created TIMESTAMPTZ NOT NULL
);

CREATE TABLE password_resets (
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  code_hash TEXT NOT NULL,
  expires TIMESTAMPTZ NOT NULL
);

-- Append-only history. No foreign keys on purpose: entries outlive deleted users and projects.
CREATE TABLE audit (
  id TEXT PRIMARY KEY,                              -- time-ordered id, used as the paging cursor
  at TIMESTAMPTZ NOT NULL,
  user_id TEXT,
  user_email TEXT,
  action TEXT NOT NULL,
  entity TEXT NOT NULL,
  entity_id TEXT,
  project TEXT,
  summary TEXT,
  changes JSONB
);
CREATE INDEX idx_audit_project ON audit (project, id);
CREATE INDEX idx_audit_entity ON audit (entity, id);
